PROGRAM p_mguard_3_motor
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    G1 : BOOL;
    G2 : BOOL;
    G3 : BOOL;
END_VAR

VAR_OUTPUT
    Motor : BOOL;
END_VAR

VAR
    motor_state : BOOL := FALSE;
    start_timer : TON;
    stop_timer : TON;
END_VAR

// Check if all guards are closed
IF G1 AND G2 AND G3 THEN
    // If Stop button is pressed, reset motor state and timers
    IF StopPB THEN
        motor_state := FALSE;
        start_timer(IN := FALSE);
        stop_timer(IN := FALSE);
    ELSIF StartPB THEN
        // If Start button is pressed and motor is not already running, start motor
        IF NOT motor_state THEN
            motor_state := TRUE;
            start_timer(IN := TRUE, PT := T#0s);
        END_IF;
    END_IF;
ELSE
    // If any guard is open, stop the motor and reset timers
    motor_state := FALSE;
    start_timer(IN := FALSE);
    stop_timer(IN := FALSE);
END_IF;

// Update motor output based on motor state
Motor := motor_state;
END_PROGRAM

