PROGRAM p_estop_3_motor
VAR_INPUT
    Start : BOOL;
    Stop : BOOL;
    E1 : BOOL;
    E2 : BOOL;
    E3 : BOOL;
END_VAR
VAR_OUTPUT
    Motor : BOOL;
END_VAR
VAR
    estop_active : BOOL := FALSE;
    motor_timer : TON;
END_VAR

motor_timer(IN := estop_active OR Stop, PT := T#0s);

IF E1 = FALSE THEN
    estop_active := TRUE;
ELSIF E2 = FALSE THEN
    estop_active := TRUE;
ELSIF E3 = FALSE THEN
    estop_active := TRUE;
END_IF;

IF Start AND NOT estop_active AND NOT motor_timer.Q THEN
    Motor := TRUE;
ELSE
    Motor := FALSE;
END_IF;

