PROGRAM p_estop_3_motor
VAR_INPUT
    Start : BOOL;
    Stop : BOOL;
    E1 : BOOL;
    E2 : BOOL;
    E3 : BOOL;
END_VAR
VAR_OUTPUT
    Motor : BOOL;
END_VAR
VAR
    motor_latched : BOOL := FALSE;
    estop_active : BOOL := FALSE;
    estop_timer : TON;
END_VAR

// Check for any e-stop activation
estop_active := E1 OR E2 OR E3;

// If any e-stop is active, stop the motor and reset the latch
IF estop_active THEN
    Motor := FALSE;
    motor_latched := FALSE;
    estop_timer(IN := TRUE, PT := T#0s);
ELSE
    // If no e-stop is active, handle start and stop commands
    IF Start AND NOT motor_latched THEN
        Motor := TRUE;
        motor_latched := TRUE;
    ELSIF Stop THEN
        Motor := FALSE;
        motor_latched := FALSE;
    END_IF;
END_IF;

// Reset the motor if e-stop is activated again after a short delay
IF estop_timer.Q THEN
    motor_latched := FALSE;
END_IF;

END_PROGRAM

PROGRAM p_estop_3_motor
VAR_INPUT
    Start : BOOL;
    Stop : BOOL;
    E1 : BOOL;
    E2 : BOOL;
    E3 : BOOL;
END_VAR

VAR_OUTPUT
    Motor : BOOL;
END_VAR

VAR
    motor_on : BOOL := FALSE;
    estop_active : BOOL := FALSE;
    estop_timer : TON;
END_VAR

// Check for any active estop
estop_active := NOT (E1 AND E2 AND E3);

// If estop is active or stop signal is received, turn off the motor
IF estop_active OR Stop THEN
    motor_on := FALSE;
ELSE
    // If start signal is received and estop is not active, turn on the motor
    IF Start AND NOT estop_active THEN
        motor_on := TRUE;
    END_IF;
END_IF;

// Update the motor output
Motor := motor_on;

// Reset estop timer if estop is cleared
IF NOT estop_active THEN
    estop_timer(IN := TRUE, PT := T#0s);
ELSE
    estop_timer(IN := FALSE);
end_if;

END_PROGRAM

