    Reset : BOOL;
END_VAR
VAR_OUTPUT
    Pump : BOOL;
END_VAR
VAR
    Count : INT := 0;
    PrevPulse : BOOL := FALSE;
END_VAR
VAR CONSTANT
    MAX_COUNT : INT := 5;
END_VAR

// Check for rising edge of Pulse
PrevPulse := NOT Pulse;

IF Pulse AND NOT PrevPulse THEN
    IF Count < MAX_COUNT THEN
        Count := Count + 1;
    END_IF;
ELSIF Reset THEN
    Count := 0;
END_IF;

// Assert Pump when Count reaches 5
Pump := (Count = MAX_COUNT);
END_PROGRAM

PROGRAM p_cnt_5_pump
VAR_INPUT
    Pulse : BOOL;
    Reset : BOOL;
END_VAR
VAR_OUTPUT
    Pump : BOOL;
END_VAR
VAR
    Count : INT := 0;
    PrevPulse : BOOL := FALSE;
    CountTimer : TON;
END_VAR

-- Detect rising edge of Pulse
PrevPulse := Pulse;

-- Check for reset
IF Reset THEN
    Count := 0;
    Pump := FALSE;
    PrevPulse := FALSE;
END_IF;

-- Count rising edges of Pulse
IF Pulse AND NOT PrevPulse THEN
    IF Count < 5 THEN
        Count := Count + 1;
    END_IF;
END_IF;

-- Assert Pump when Count reaches 5
IF Count = 5 THEN
    Pump := TRUE;
END_IF;

-- Reset CountTimer if Pump is asserted
IF Pump THEN
    CountTimer(IN := TRUE, PT := T#0s);
    IF CountTimer.Q THEN
        Pump := FALSE;
        Count := 0;
        PrevPulse := FALSE;
    END_IF;
END_IF;

END_PROGRAM

