    Enable : BOOL;
    Fault : BOOL;
END_VAR
VAR_OUTPUT
    Pump : BOOL;
END_VAR
VAR
    PumpTimer : TON;
END_VAR

// Initialize the timer
PumpTimer(IN := FALSE, PT := T#0s);

// Control logic for the pump
IF Fault THEN
    // If there is a fault, turn off the pump immediately
    Pump := FALSE;
    PumpTimer(IN := FALSE);
ELSIF Enable AND Demand THEN
    // If enabled and demand is present, start or keep the pump running
    Pump := TRUE;
    PumpTimer(IN := TRUE, PT := T#0s);
ELSE
    // If not enabled or demand is absent, stop the pump if it was running
    Pump := FALSE;
    PumpTimer(IN := FALSE);
END_IF;

// Reset the pump if it has been running for more than 5 seconds to prevent overheating
IF PumpTimer.Q THEN
    Pump := FALSE;
    PumpTimer(IN := FALSE);
END_IF;
