    Fan := FALSE;
    Start := FALSE;
    estop_timer(IN := TRUE, PT := T#0.5s);
ELSE
    // If no e-stop is active, check the start and stop signals
    IF Start AND NOT estop_timer.Q THEN
        Fan := TRUE;
    ELSEIF Stop THEN
        Fan := FALSE;
    END_IF;
END_IF;

// Reset the e-stop timer if it has timed out
IF estop_timer.Q THEN
    estop_timer(IN := FALSE);
END_IF;
