VAR_INPUT
    Start : BOOL;
    Stop : BOOL;
    E1 : BOOL;
    E2 : BOOL;
    E3 : BOOL;
END_VAR

VAR_OUTPUT
    Fan : BOOL;
END_VAR

VAR
    estop_active : BOOL := FALSE;
    estop_timer : TON;
END_VAR

// Check for any active e-stop
estop_active := E1 OR E2 OR E3;

// Reset the timer if there is no active e-stop
IF NOT estop_active THEN
    estop_timer(IN := FALSE);
END_IF;

// If there is an active e-stop, reset the fan and start the timer
IF estop_active THEN
    Fan := FALSE;
    estop_timer(IN := TRUE, PT := T#0.1s);
END_IF;

// If the timer has not yet expired, keep the fan off
IF estop_timer.Q AND estop_active THEN
    Fan := FALSE;
END_IF;

// If there is no active e-stop and Start is pressed, turn on the fan
IF NOT estop_active AND Start THEN
    Fan := TRUE;
END_IF;

// If Stop is pressed, turn off the fan
IF Stop THEN
    Fan := FALSE;
END_IF;

END_PROGRAM

