    Reset : BOOL;
END_VAR
VAR_OUTPUT
    Fan : BOOL;
END_VAR
VAR
    Count : INT := 0;
    PrevPulse : BOOL := FALSE;
    PulseTimer : TON;
END_VAR

// Detect rising edge of Pulse
PulseTimer(IN := Pulse AND NOT PrevPulse, PT := T#0s);

IF PulseTimer.Q THEN
    // Increment Count if Pulse is detected
    IF Count < 5 THEN
        Count := Count + 1;
    END_IF;
    // Set PrevPulse for next cycle detection
    PrevPulse := TRUE;
END_IF;

// Reset logic
IF Reset THEN
    Count := 0;
    PrevPulse := FALSE;
END_IF;

// Assert Fan when Count reaches 5
Fan := (Count = 5);
END_PROGRAM

