    ELSE
        // Otherwise, start the timer
        MixerTimer(IN := TRUE, PT := T#0s);
    END_IF;
END_IF;

// Stop the mixer if StopPB is pressed or any guard opens
IF StopPB OR NOT G1 OR NOT G2 OR NOT G3 OR NOT G4 THEN
