    Mixer := FALSE;
ELSIF Counter.Q THEN
    IF Count < 5 THEN
        Count := Count + 1;
    END_IF;
    PrevPulse := TRUE;
    IF Count = 5 THEN
        Mixer := TRUE;
    END_IF;
END_IF;

IF NOT Pulse THEN
    PrevPulse := FALSE;
END_IF;
