        // If Stop is pressed or Start is not pressed, stop the blower
        BlowerState := FALSE;
        BlowerTimer(IN := FALSE, PT := T#0s);
    END_IF;
END_IF;

// Ensure blower does not turn on if any e-stop is activated
IF NOT E1 THEN
    Blower := FALSE;
