PROGRAM p_cnt_2_spindle
VAR_INPUT
    Pulse : BOOL;
    Reset : BOOL;
END_VAR
VAR_OUTPUT
    Spindle : BOOL;
END_VAR
VAR
    Count : INT := 0;
    PrevPulse : BOOL := FALSE;
END_VAR
VAR_CONSTANTS
    MAX_COUNT : INT := 2;
END_VAR

PrevPulse := Pulse AND NOT Pulse;

IF Reset THEN
    Count := 0;
    Spindle := FALSE;
ELSIF Pulse AND NOT PrevPulse THEN
    IF Count < MAX_COUNT THEN
        Count := Count + 1;
    END_IF;
    IF Count = MAX_COUNT THEN
        Spindle := TRUE;
    ELSE
        Spindle := FALSE;
    END_IF;
END_IF;

END_PROGRAM

PROGRAM p_cnt_2_spindle
VAR_INPUT
    Pulse : BOOL;
    Reset : BOOL;
END_VAR
VAR_OUTPUT
    Spindle : BOOL;
END_VAR
VAR
    Count : INT := 0;
    PrevPulse : BOOL := FALSE;
    TmrReset : TON;
END_VAR

// Update edge detection for Pulse
PrevPulse := Pulse AND NOT PrevPulse;

// Increment Count on rising edge of Pulse if less than 2
IF Pulse AND NOT PrevPulse THEN
    IF Count < 2 THEN
        Count := Count + 1;
    END_IF;
END_IF;

// Set Spindle when Count reaches 2
Spindle := Count = 2;

// Reset Count and Spindle on Reset input
IF Reset THEN
    Count := 0;
    Spindle := FALSE;
    TmrReset(IN := TRUE, PT := T#0s);
END_IF;

// Ensure Count does not exceed 2
IF Count > 2 THEN
    Count := 2;
END_IF;

END_PROGRAM

