IF Enable THEN
    IF OverTemp THEN
        Auger := FALSE;
        AugerTimer(IN := FALSE);
    ELSIF Demand THEN
        Auger := TRUE;
        AugerTimer(IN := TRUE, PT := T#0s);
    ELSE
        Auger := FALSE;
        AugerTimer(IN := FALSE);
