PROGRAM p_ovr_auger
VAR_INPUT
    Demand : BOOL;
    Enable : BOOL;
    Fault : BOOL;
END_VAR
VAR_OUTPUT
    Auger : BOOL;
END_VAR
VAR
    AugerTimer : TON;
END_VAR

// Reset the timer if Fault is TRUE or Demand is FALSE
IF Fault OR NOT Demand THEN
    AugerTimer(IN := FALSE);
ELSE
    // Start the timer if Enable is TRUE and Demand is TRUE
    IF Enable AND Demand THEN
        AugerTimer(IN := TRUE, PT := T#0s);
    END_IF;
END_IF;

// Set Auger based on timer output and Fault
Auger := AugerTimer.Q AND NOT Fault;

END_PROGRAM

PROGRAM p_ovr_auger
