    Enable : BOOL;
    Fault : BOOL;
END_VAR
VAR_OUTPUT
    Auger : BOOL;
END_VAR
VAR
    AugerControl : BOOL := FALSE;
END_VAR

// Update the control signal based on Demand, Enable, and Fault
AugerControl := Demand AND Enable AND NOT Fault;

// Assign the control signal to the output
Auger := AugerControl;
END_PROGRAM

PROGRAM p_ovr_auger
VAR_INPUT
    Demand : BOOL;
    Enable : BOOL;
    Fault : BOOL;
END_VAR
VAR_OUTPUT
    Auger : BOOL;
END_VAR
VAR
    AugerTimer : TON;
END_VAR

// Check if Fault is TRUE, which overrides all other conditions
IF Fault THEN
    Auger := FALSE;
ELSE
    // If Fault is not TRUE, check if Enable is TRUE and Demand is TRUE
    IF Enable AND Demand THEN
        Auger := TRUE;
        // Start the timer to ensure non-latching behavior
        AugerTimer(IN := TRUE, PT := T#0s);
    ELSE
        Auger := FALSE;
        // Reset the timer
        AugerTimer(IN := FALSE);
    END_IF;
END_IF;

// Ensure Auger remains FALSE if the timer is active
IF AugerTimer.Q THEN
    Auger := FALSE;
END_IF;

END_PROGRAM

