    ReqB : BOOL;
END_VAR

VAR_OUTPUT
    DoorA : BOOL;
    DoorB : BOOL;
END_VAR

VAR
    T_DoorA : TON;
    T_DoorB : TON;
    ActiveDoor : INT;
END_VAR

T_DoorA(IN := ReqA, PT := T#0s);
T_DoorB(IN := ReqB AND NOT T_DoorA.Q, PT := T#0s);

IF T_DoorA.Q THEN
    DoorA := TRUE;
    DoorB := FALSE;
    ActiveDoor := 1;
ELSIF T_DoorB.Q THEN
    DoorA := FALSE;
    DoorB := TRUE;
    ActiveDoor := 2;
ELSE
    DoorA := FALSE;
    DoorB := FALSE;
    ActiveDoor := 0;
END_IF;

IF (ActiveDoor = 1 AND T_DoorB.Q) OR (ActiveDoor = 2 AND T_DoorA.Q) THEN
    DoorA := FALSE;
    DoorB := FALSE;
END_IF;
END_PROGRAM

